import{z as d,x as m,o as n,c as A,q as l,j as E,D as t,d as r,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"有限域 GF(2ⁿ)","description":"","frontmatter":{"title":"有限域 GF(2ⁿ)","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/finite-field-gf2n.md","filePath":"cs/finite-field-gf2n.md","lastUpdated":1791063341000}'),p={name:"cs/finite-field-gf2n.md"};function h(B,a,F,b,D,x){const i=m("Mermaid");return n(),A("div",null,[a[2]||(a[2]=l('<h1 id="有限域-gf-2n" tabindex="-1">有限域 GF(2ⁿ) <a class="header-anchor" href="#有限域-gf-2n" aria-label="Permalink to &quot;有限域 GF(2ⁿ)&quot;">​</a></h1><div class="epigraph"><p>$\\mathbb{F}_2[x]$ 模一个 $n$ 次不可约多项式，得到 $2^n$ 元域；字节上的 AES 与 RS 符号都在这里做乘。</p><footer>—— 据 Lidl and Niederreiter, Finite Fields；Daemen and Rijmen, AES 整理</footer></div><p>上一课<a href="/cs/group-ring-field">群环域</a> 说有限域阶为 \\(p^k\\)。缺口是 <strong>\\(p=2\\) 的显式构造</strong>：比特串当多项式，\\(\\oplus\\) 为加，乘模不可约 \\(p(x)\\)。RS 课已经用过「能除」；本课把 \\(\\mathrm{GF}(256)\\) 钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathbb{F}_2[x]/(p(x))\\)，\\(p\\) 不可约次数 \\(n\\)，是 \\(2^n\\) 元域，在同构意义下唯一。元素：\\(n\\) 比特。加：按位异或。乘：多项式乘再模 \\(p(x)\\)。AES 用 \\(x^8+x^4+x^3+x+1\\)。求逆：扩展欧几里得在 \\(F_2[x]\\) 上，或 \\(a^{254}\\)（费马，\\(|\\mathbb{F}^\\times|=255\\)）。</p><p>不可约 \\(\\ne\\) 本原。本原多项式使 \\(x\\) 生成乘群，便于实现。本课能乘即可。</p><h3 id="不是" tabindex="-1">不是 \\(\\mathbb{Z}/2^n\\mathbb{Z}\\) <a class="header-anchor" href="#不是" aria-label="Permalink to &quot;不是 $\\mathbb{Z}/2^n\\mathbb{Z}$&quot;">​</a></h3><p>\\(\\mathbb{Z}/256\\mathbb{Z}\\) 有零因子，不是域。AES 的字节乘绝不是模 256 整数乘。这是最常见的混层。</p><p><span class="marginnote">Lidl–Niederreiter 有限域手册。Rijndael 规格写明多项式。本课不把 S 盒当定义；S 盒是仿射+逆，协议层。</span></p><p><span class="marginnote">术语翻译：「不可约」就是「在 \\(\\mathbb{F}_2[x]\\) 里除不尽」——找不到两个更低次的多项式乘起来等于它，角色像整数里的素数。正因为除不尽，拿它当模数做乘法才不会把两个非零元乘成零，域才立得起来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(\\mathrm{GF}(4)=\\mathbb{F}_2[x]/(x^2+x+1)\\) 列出四元乘表。对照 RS：符号在 \\(\\mathrm{GF}(2^8)\\) 时一个错是一个域元。指出：硬件上乘可用指令或表。</p><p><span class="marginnote">数字实例：GF(4) 的四个元素是 00、01、10、11。算一次乘：10 × 11 = \\(x\\cdot(x+1) = x^2+x\\)；在 \\(\\mathbb{F}_2\\) 里 \\(x^2+x = (x^2+x+1)+1\\)，模 \\(x^2+x+1\\) 后剩 1，所以 10 × 11 = 01，两者互为逆元——这就是「能做除法」的样子。</span></p>',13)),(n(),E(o,null,{default:t(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20POLY%5B%22F2%20%E5%A4%9A%E9%A1%B9%E5%BC%8F%E6%A8%A1%E4%B8%8D%E5%8F%AF%E7%BA%A6%22%5D%20--%3E%20FLD%5B%22GF(2%5En)%22%5D%0A%20%20FLD%20--%3E%20ADD%5B%22%E5%8A%A0%20%3D%20%E5%BC%82%E6%88%96%22%5D%0A%20%20FLD%20--%3E%20MUL%5B%22%E4%B9%98%E5%86%8D%E5%8F%96%E6%A8%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有了 \\(\\mathrm{GF}(2^n)\\)，线性码、AES、GCM 的域运算有同一载体。下一课乘群的生成元与离散对数在奇素数域上更常讲，但 \\(\\mathrm{GF}(2^n)^\\times\\) 同样循环。本课不碰离散对数难度。",-1)),a[5]||(a[5]=e("p",null,"扩域塔（\\(\\mathrm{GF}((2^8)^2)\\)）点名，不构造。",-1)),a[6]||(a[6]=e("p",null,"不可约性可用筛或查表；\\(n=8\\) 的 AES 多项式固定。乘法可用 CLMUL 类指令。求逆：\\(a^{2^n-2}=a^{-1}\\)（\\(a\\neq 0\\)）。\\(\\mathbb{Z}/2^n\\mathbb{Z}\\) 与 \\(\\mathrm{GF}(2^n)\\) 基数相同、运算不同，混用会把 AES 与模幂写错。RS 符号宽 \\(n\\) 时字母表就是这个域。",-1)),(n(),E(o,null,{default:t(()=>[s(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22Z%2F256Z%3A%20%E6%A8%A1%20256%20%E6%95%B4%E6%95%B0%22%5D%20--%3E%20D%5B%22%E9%9B%B6%E5%9B%A0%E5%AD%90%3A%2016%20%C3%97%2016%20%3D%20256%20%E2%89%A1%200%22%5D%0A%20%20D%20--%3E%20NF%5B%22%E9%9D%9E%E9%9B%B6%E5%85%83%E8%83%BD%E4%B9%98%E5%87%BA%E9%9B%B6%3A%20%E4%B8%8D%E6%98%AF%E5%9F%9F%22%5D%0A%20%20G%5B%22GF(256)%3A%20%E6%A8%A1%E4%B8%8D%E5%8F%AF%E7%BA%A6%20p(x)%22%5D%20--%3E%20NOD%5B%22%E9%9D%9E%E9%9B%B6%E5%85%83%E4%B8%8E%20p(x)%20%E6%97%A0%E5%85%AC%E5%9B%A0%E5%AD%90%22%5D%0A%20%20NOD%20--%3E%20INV%5B%22%E6%AF%8F%E4%B8%AA%E9%9D%9E%E9%9B%B6%E5%85%83%E9%83%BD%E6%9C%89%E9%80%86%E5%85%83%22%5D%0A%20%20INV%20--%3E%20F%5B%22%E6%98%AF%E5%9F%9F%3A%20%E5%9B%9B%E5%88%99%E9%83%BD%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：初学者以为 GF(256) 的乘法就是「模 256 的整数乘」。两者元素都恰好 256 个，运算却完全不同：整数版里 16 × 16 ≡ 0，零因子毁掉除法；域版每个非零字节都有逆。AES 的字节乘是后者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证存在不可约多项式，不引入迹函数。不写 AES 轮函数。后课默认：字节域 = \\(\\mathrm{GF}(2^8)\\) 多项式基。下一课生成元与离散对数。</p><p>字节乘是多项式模不可约式，不是模 256 整数。AES 与 RS 共用这一载体。乘群仍循环，离散对数下一课在奇素数域上讲得更标准，结论可平移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{GF}(2^n)\\) 是 \\(\\mathbb{F}_2[x]\\) 模不可约 \\(n\\) 次式。</li><li>加是异或；不是模 \\(2^n\\) 整数环。</li><li>AES、RS 符号在此做四则。</li><li>出处：Lidl and Niederreiter；Daemen and Rijmen, AES。</li></ul>',6))])}const u=d(p,[["render",h]]);export{S as __pageData,u as default};
